export type InfantryWeaponCategory = "archaic" | "pistol" | "rifle" | "shotgun" | "smg" | "grenade" | "support";
export type InfantryWeaponType = "melee" | "standard" | "support";
/** B ballistic, E energy, M missile, P point-blank (TM p.148). */
export type InfantryDamageType = "B" | "E" | "M" | "P";

export const INFANTRY_WEAPON_CATEGORIES: { tag: InfantryWeaponCategory; name: string }[] = [
    { tag: "archaic", name: "Archaic Weapons" },
    { tag: "pistol", name: "Pistols" },
    { tag: "rifle", name: "Rifles" },
    { tag: "shotgun", name: "Shotguns" },
    { tag: "smg", name: "Submachine Guns" },
    { tag: "grenade", name: "Grenades (Thrown)" },
    { tag: "support", name: "Support Weapons" },
];

export interface IInfantryWeapon extends ICatalogStanding {
    tag: string;
    name: string;
    /** Other spellings, e.g. MegaMek's names. */
    altNames?: string[];
    category: InfantryWeaponCategory;
    /** "universal" is the table's "IS / Clan". */
    techBase: CatalogTechBase;
    techRating: string;
    /** Size class; it matters to Support Vehicle construction only. */
    size: "small" | "medium";
    type: InfantryWeaponType;
    damageType: InfantryDamageType;
    /** Special feature codes: A anti-aircraft, B heavy burst, F flame-based, N non-penetrating (TM p.148). */
    special: string;
    baseRange: number;
    /** Damage per weapon; a platoon's damage is rounded only once it is summed. */
    damage: number;
    /** Troopers needed to work the weapon. */
    crew: number;
    /** The table's crew value "1E": one trooper, +1 to-hit in the platoon's own hex (TM p.149). */
    encumbering: boolean;
    inferno: boolean;
    battleValue: number;
    /** C-bills; null where the cost table has no row for the weapon. Unknown is not zero. */
    cost: number | null;
    /** Availability by era (Age of War - Succession Wars - 3050+); null with the cost. */
    availability: string | null;
    /**
     * Introduction, extinction and reintroduction years from the cost table's date columns, Inner Sphere and Clan.
     * "PS" is Pre-Spaceflight and "ES" Early Spaceflight, both before the Age of War. Null is the table's dash or
     * "NA", or a weapon with no row in the table: no date, which is not the same as year zero.
     */
    introducedIS: InfantryWeaponDate;
    introducedClan: InfantryWeaponDate;
    extinctIS: number | null;
    extinctClan: number | null;
    reintroducedIS: number | null;
    /**
     * The table's "Weight of Weapon / Ammo (Shots)" column (TM p.149): the weapon and one standard clip in
     * kilograms, and the clip's shots and bursts. They play no part in building a platoon; Support Vehicles,
     * battle armor and buildings mount weapons by them. Null is the table's "NA".
     */
    weight: number;
    ammoWeight: number | null;
    shots: number | null;
    bursts: number | null;
    /** The table's "1-D": a single-use weapon, thrown or fired once and discarded. */
    disposable: boolean;
    /**
     * The cost table's second figure, the weapon's ammunition, in C-bills (TM pp.298-301). Null where the table
     * gives no number: "NA", a single-use weapon, power cells, or a weapon with no row. Inferno rounds have no
     * row of their own: the record repeats the weapon's figure, and getInfantryClipCost prices the clip.
     */
    ammoCost: number | null;
    /** The cost table's energy-cell footnote: 200 C-bills covers a supply of power cells for combat (TM p.301). */
    powerCells: boolean;
    /** Source of a record from outside the TechManual tables; unset = TM. */
    book?: string;
    page?: number;
    /** Where a Custom Homebrew record comes from, and how it was converted. */
    notes?: string;
}

/** What a supply of power cells for one energy-cell weapon costs (TM p.301, footnote). */
export const INFANTRY_POWER_CELL_COST = 200;

/**
 * Inferno rounds against standard ones. The cost table has no inferno rows, so the price is inferred from SRM
 * ammunition, where a ton of inferno rounds is 13,500 C-bills against 27,000 (user ruling, 2026-10-07).
 */
export const INFANTRY_INFERNO_AMMO_COST_FACTOR = 0.5;

/** What one clip costs, or null where the table gives no number. */
export const getInfantryClipCost = (weapon: IInfantryWeapon): number | null =>
    weapon.ammoCost === null ? null : weapon.ammoCost * (weapon.inferno ? INFANTRY_INFERNO_AMMO_COST_FACTOR : 1);

export type InfantryWeaponDate = number | "PS" | "ES" | null;

/** Is the weapon allowed at this rules level? Only Custom Homebrew records carry a level of their own. */
export const isInfantryWeaponAtRulesLevel = (weapon: IInfantryWeapon, rulesLevel: number): boolean =>
    (weapon.rulesLevel ?? 0) <= rulesLevel;

/** May only be carried by motorized and mechanized (tracked) platoons, and holds them to 2 MP (TM p.352, footnote). */
export const INFANTRY_SUPPORT_PPC_TAG = "inf-particle-cannon-support";

/** No primary weapon counts for more than this per trooper; one that would also gives heavy burst (TM p.150). */
export const INFANTRY_MAX_PRIMARY_DAMAGE = 0.6;

