export const findInfantryWeapon = (tag: string): IInfantryWeapon | null =>
    infantryWeapons.find((weapon) => weapon.tag === tag) ?? null;

/**
 * Can a platoon of this technology base carry the weapon between two years? The weapon must have been introduced
 * by the end of the span and must not be extinct for all of it. A weapon both bases use that has no Clan date of
 * its own goes by its Inner Sphere dates, as the Clans carried the Star League's equipment with them. A weapon
 * with no date at all is not ruled out.
 */
export const isInfantryWeaponAvailable = (weapon: IInfantryWeapon, techBase: "is" | "clan", yearStart: number, yearEnd: number | null): boolean => {
    const end = yearEnd ?? Number.POSITIVE_INFINITY;
    const ownIntroduced = techBase === "clan" ? weapon.introducedClan : weapon.introducedIS;
    const introduced = ownIntroduced ?? (weapon.techBase === "universal" ? weapon.introducedIS ?? weapon.introducedClan : null);
    if (typeof introduced === "number" && introduced > end) return false;
    const extinct = techBase === "clan" ? weapon.extinctClan : weapon.extinctIS;
    if (extinct !== null && extinct < yearStart) {
        const reintroduced = techBase === "clan" ? null : weapon.reintroducedIS;
        if (reintroduced === null || reintroduced > end) return false;
    }
    return true;
};
